import { useQueryClient } from '@tanstack/react-query';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { sheetKey, useSheet } from './sheet';

function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const loaded = useSheet(sheet);

  if (!user) return null;
  return (
    <form
      data-testid="sheet-form"
      onSubmit={(e) => {
        e.preventDefault();
        const id = input.trim();
        if (!id) return;
        // Loading an id again re-reads it from the store.
        void queryClient.invalidateQueries({ queryKey: sheetKey(id) });
        setSheet(id);
      }}
    >
      <input data-testid="sheet-id-input" placeholder="Sheet id" value={input} onChange={(e) => setInput(e.target.value)} />
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {loaded.data && (
        <span>
          {' '}Sheet <strong data-testid="sheet-current-id">{loaded.data.id}</strong>
        </span>
      )}
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 10, Component: SheetPicker });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string };

/** Every per-sheet query key starts with ['sheet', id], so loading a sheet re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;

export function useSheet(id: string) {
  return useQuery({
    queryKey: sheetKey(id),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}`),
    enabled: id !== '',
  });
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { defineSlot } from '../Slot';

/** The shell's header: who is signed in and which sheet is active. */
export const AppHeader = defineSlot('app.header');
import { defineSlot } from '../Slot';

/**
 * The shell's nav bar. Every page contributes its own link — the shell never lists the pages.
 * A nav link carries `data-testid="nav-<section>"` (the test contract; CLAUDE.md).
 */
export const AppNav = defineSlot('app.nav');
import { createFileRoute } from '@tanstack/react-router';

// The base home page (empty). A page is a file under routes/ — `createFileRoute('<its url>')` —
// with its nav link under features/.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  return <p data-testid="home-empty">Nothing here yet.</p>;
}
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});
import { Link } from '@tanstack/react-router';
import { AppNav } from '../../slots/defs/appNav';

// WORKED EXAMPLE of the one mechanism every shared region uses. This file is the whole of Home's
// presence in the nav bar; the shell was not touched to put it there. A new page adds its own file
// exactly like this one.
export const contribution = AppNav.fill({
  order: 0,
  Component: () => (
    <Link to="/" data-testid="nav-home">
      Home
    </Link>
  ),
});

